export const activeCases=[{id:'root',name:'Mineral uptake by root hairs',left:4,right:12,direction:'right',leftName:'Soil solution',rightName:'Root-hair cell',substance:'Mineral ions',purpose:'Plants need mineral ions for healthy growth.'},{id:'gut',name:'Sugar absorption from the gut',left:4,right:12,direction:'right',leftName:'Gut solution',rightName:'Blood side',substance:'Sugar molecules',purpose:'Absorbed sugars can be used in cell respiration. The gut lining is simplified to one transport boundary.'},{id:'energy',name:'Reverse the layout',left:12,right:4,direction:'left',leftName:'Cell side',rightName:'Dilute solution',substance:'Mineral ions',purpose:'Direction depends on the supplied gradient and transport route, not which side is drawn on the page.'}];
export function activeFrame(id='root',energy=false,value=0){const c=activeCases.find(c=>c.id===id)||activeCases[0],step=Math.max(0,Math.min(3,Math.floor(Number(value)||0))),moved=energy?step:0,left=c.left+(c.direction==='right'?-moved:moved);return{...c,step,moved,left,right:16-left,energy:Boolean(energy)};}
export const comparisonCases=[
{id:'oxygen',title:'Oxygen into a respiring cell',substance:'Oxygen',left:12,right:4,leftName:'Outside',rightName:'Cell',direction:'right',process:'diffusion',why:'Oxygen moves overall down its concentration gradient. This diffusion does not use energy from respiration.'},
{id:'water',title:'Water across a partially permeable membrane',substance:'Water',left:3,right:9,leftName:'Dilute solution',rightName:'Concentrated solution',direction:'right',process:'osmosis',why:'The values here represent solute concentration. Water moves overall from the dilute solution to the concentrated solution through a partially permeable membrane.'},
{id:'mineral',title:'Mineral ions into a root hair',substance:'Mineral ions',left:4,right:12,leftName:'Soil solution',rightName:'Root-hair cell',direction:'right',process:'active',why:'Net mineral-ion uptake from dilute soil into a more concentrated cell is against the gradient and requires energy from respiration.'},
{id:'carbon',title:'Carbon dioxide leaving a cell',substance:'Carbon dioxide',left:4,right:12,leftName:'Outside',rightName:'Cell',direction:'left',process:'diffusion',why:'With the higher carbon dioxide concentration inside, net diffusion is out of the cell. Diffusion is not always inward.'},
{id:'sugar',title:'Sugar from gut to blood',substance:'Sugar',left:4,right:12,leftName:'Gut solution',rightName:'Blood side',direction:'right',process:'active',why:'The supplied gut concentration is lower than blood concentration. This net absorption requires active transport, using respiration energy.'}
];
export function transportOutcome(c,process,energy){const correct=process===c.process;if(!correct)return{moves:false,reason:process==='osmosis'&&c.substance!=='Water'?'Osmosis describes water, not this substance.':process==='diffusion'&&c.process==='active'?'Diffusion would favour the opposite net direction.':'This mechanism does not match the specified substance and gradient.'};if(process==='active'&&!energy)return{moves:false,reason:'This active route needs energy from respiration. Passive particle movement has not stopped.'};return{moves:true,reason:c.why};}
export const bothEnergyStates=r=>r?.states?.includes('on')&&r?.states?.includes('off');
